INSERT INTO `tb_faq` (`id`, `pertanyaan`, `jawaban`, `date_create`) VALUES
(1, 'Berapa lama proses instalasi setelah berlangganan?', 'Proses instalasi biasanya memakan waktu 3-7 hari kerja setelah pembayaran dikonfirmasi, tergantung kondisi lokasi.', '2026-07-07 13:07:29'),
(2, 'Apakah ada biaya pemasangan?', 'Biaya pemasangan bervariasi tergantung paket dan jarak lokasi dari titik jaringan terdekat. Tim kami akan melakukan survei terlebih dahulu.', '2026-07-07 13:07:29'),
(3, 'Apakah kecepatan internet dijamin stabil?', 'Ya, kami menggunakan jaringan private dengan SLA yang menjamin kestabilan kecepatan sesuai paket yang dipilih.', '2026-07-07 13:07:29'),
(4, 'Bagaimana cara menghubungi support jika ada gangguan?', 'Anda bisa menghubungi tim support kami melalui email di info@cjpnetwork.com atau melalui formulir kontak di halaman ini.', '2026-07-07 13:07:29'),
(5, 'Apakah bisa upgrade paket di tengah masa berlangganan?', 'Bisa. Anda dapat mengajukan upgrade paket kapan saja melalui tim customer service kami, dan penyesuaian tagihan akan dihitung secara prorata.', '2026-07-07 13:07:29');
