INSERT INTO `tb_profile` (`id`, `nama_perusahaan`, `akronim`, `logo`, `email`, `no_telp`, `persentasi`, `brosur`, `alamat1`, `alamat2`, `url_alamat2`, `url_alamat1`, `detail`, `tag_line`) VALUES
(1, 'PT Connecti Jelajah Priangan', 'PT. CJP', 'logo-cjp.png', 'info@cjpnetwork.com', '02230500111', 'COOMINGSOON', 'broadband.png', 'Jl. Raya Leuwigajah No. 233 Kel. Utama, Kec. Cimahi Selatan, Kota Cimahi, 40533', 'Jl. Reog No.18, Turangga, Kec. Lengkong, Kota Bandung, Jawa Barat 40264', 'https://www.google.com/maps/place/PT.CJP+(+Connecti+Jelajah+Priangan+)/@-6.9369931,107.6293815,17z/data=!3m1!4b1!4m6!3m5!1s0x2e68e8666588e463:0xddd296d9a427e333!8m2!3d-6.9369931!4d107.6319564!16s%2Fg%2F11c1tt7q4w?entry=ttu&g_ep=EgoyMDI1MDIxOC4wIKXMDSoASAFQAw%3', 'https://goo.gl/maps/ccEZe7mcGiYsNq4n7', 'adalah nama perusahaan yang berkembang dan telah dipercaya oleh berbagai pihak, baik pemerintah daerah, BUMN, BUMD maupun pihak swasta. Keberhasilan ini tidak lepas dari dukungan semua partner kami yang selalu mendukung kemajuan PT. CJP.', '');
INSERT INTO `tb_section` (`id`, `id_menu`, `tag_line`, `tag_line2`, `detail`, `detail2`, `detail3`) VALUES
(1, 1, 'Get Your IT Solution', '', 'Kami Adalah Perusahaan Penyedia Layanan Solusi IT dan Developer Berbagai Macam Aplikasi, dengan Mengutamakan Kepuasan pelanggan :).', '', ''),
(2, 2, '', '', '\"Kami telah mengembangkan berbagai inovasi dan kreativitas dengan semangat tinggi guna memberikan karya terbaik bagi semua\"', '', ''),
(3, 3, '', '', 'Pemanfaatan Teknologi Informasi telah menjadi bagian yang hampir tidak terpisahkan dan menyentuh berbagai aspek kehidupan manusia. Hal ini dikarenakan oleh manfaat yang dapat meningkatkan efisiensi, efektifitas, transparansi dan akuntabilitas suatu aktifitas kegiatan. Selain itu kemajuan teknologi informasi yang pesat serta potensi pemanfaatannya secara luas telah membuka peluang bagi pengaksesan, pengelolaan dan pendayagunaan informasi dalam volume yang besar secara cepat dan akurat.', '', ''),
(4, 4, '', '', '\"Kami telah mengembangkan berbagai inovasi dan kreativitas dengan semangat tinggi guna memberikan karya terbaik bagi semua\"', '', ''),
(5, 5, '', '', 'Pemanfaatan Teknologi Informasi telah menjadi bagian yang hampir tidak terpisahkan dan menyentuh berbagai aspek kehidupan manusia. Hal ini dikarenakan oleh manfaat yang dapat meningkatkan efisiensi, efektifitas, transparansi dan akuntabilitas suatu aktifitas kegiatan. Selain itu kemajuan teknologi informasi yang pesat serta potensi pemanfaatannya secara luas telah membuka peluang bagi pengaksesan, pengelolaan dan pendayagunaan informasi dalam volume yang besar secara cepat dan akurat.', '', ''),
(6, 6, '', '', '', '', ''),
(7, 7, '', '', '', '', ''),
(8, 8, '', '', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d441.05675504896635!2d107.6312526733801!3d-6.943577812267672!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x2e68e8666588e463%3A0xddd296d9a427e333!2sPT.%20CJP!5e0!3m2!1sid!2sid!4v1606880139981!5m2!1sid!2sid', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3960.9014613088307!2d107.53969801427687!3d-6.902386595012479!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x2e68e5ba55b114ff%3A0xfdccda7ba321e730!2sJl.%20Raya%20Leuwigajah%20No.233%2C%20Utama%2C%20Kec.%20Cimahi%20Sel.%2C%20Kota%20Cimahi%2C%20Jawa%20Barat%2040533!5e0!3m2!1sid!2sid!4v1612411173907!5m2!1sid!2sid', ''),
